<?php require 'admin_bootstrap.php'; $title='Enrollment Management'; $pending=$pdo->query("SELECT e.*,u.name student,u.student_id,s.code,s.name subject,s.units,o.day_name,o.start_time,o.end_time,o.room,o.section,f.name faculty_name FROM enrollments e JOIN users u ON u.id=e.student_id JOIN subjects s ON s.id=e.subject_id LEFT JOIN subject_offerings o ON o.id=e.offering_id LEFT JOIN users f ON f.id=o.faculty_id WHERE e.status='pending' ORDER BY e.created_at")->fetchAll(); $recent=$pdo->query("SELECT e.*,u.name student,u.student_id,s.code,s.name subject,o.day_name,o.start_time,o.end_time,o.room,o.section,f.name faculty_name FROM enrollments e JOIN users u ON u.id=e.student_id JOIN subjects s ON s.id=e.subject_id LEFT JOIN subject_offerings o ON o.id=e.offering_id LEFT JOIN users f ON f.id=o.faculty_id WHERE e.status<>'pending' ORDER BY e.created_at DESC LIMIT 20")->fetchAll(); require 'header.php'; admin_flash_html(); ?>
<section class="section"><div class="card-head"><div><span class="eyebrow">ENROLLMENT MANAGEMENT</span><h2>Pending Enrollment Requests</h2></div><span class="badge pending"><?=count($pending)?> Pending</span></div>
<?php if(!$pending): ?><p class="muted">No pending enrollment requests.</p><?php endif; ?>
<?php foreach($pending as $r): ?><div class="ticket"><div class="card-head"><div><b><?=e($r['student'])?></b><div class="muted"><?=e($r['student_id']?:'No Student ID')?> · <?=e($r['code'])?> — <?=e($r['subject'])?> · <?=e($r['units'])?> units</div></div><span class="badge pending">Pending</span></div><p class="muted" style="margin:7px 0"><?=e($r['day_name']??'Schedule TBD')?> <?=isset($r['start_time'])?date('g:i A',strtotime($r['start_time'])).'–'.date('g:i A',strtotime($r['end_time'])):''?> · <?=e($r['faculty_name']??'Assigned Faculty')?> · <?=e($r['room']??'')?> · Section <?=e($r['section']??'')?></p><form method="post" class="button-group"><?=admin_form_return('admin_enrollment.php')?><input type="hidden" name="action" value="enrollment_action"><input type="hidden" name="enrollment_id" value="<?=$r['id']?>"><button class="btn" name="enrollment_action" value="approved">Approve</button><button class="btn danger-btn" name="enrollment_action" value="rejected">Reject</button></form></div><?php endforeach; ?></section>
<section class="section"><div class="card-head"><div><span class="eyebrow">HISTORY</span><h2>Recent Enrollment Decisions</h2></div></div><div class="table-scroll"><table class="table"><tr><th>Student</th><th>Subject</th><th>Schedule</th><th>Status</th></tr><?php foreach($recent as $r): ?><tr><td><?=e($r['student'])?><br><span class="muted"><?=e($r['student_id']?:'')?></span></td><td><b><?=e($r['code'])?></b><br><?=e($r['subject'])?></td><td><?=e($r['day_name']?:'—')?> <?=isset($r['start_time'])?date('g:i A',strtotime($r['start_time'])).'–'.date('g:i A',strtotime($r['end_time'])):''?><br><span class="muted"><?=e($r['faculty_name']?:'')?></span></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e(ucfirst($r['status']))?></span></td></tr><?php endforeach; ?></table></div></section>
<?php require 'footer.php'; ?>
